  const mountElement: null | HTMLElement = document.getElementById('app-root');

  if (mountElement === null) {
    console.error(`Missing app mount element`);
    return;
  }

  const options = {};
  ReactDOM.createRoot(mountElement, options).render(
    <App/>
  );
});

