async function resetStoryEnvironment() {
  MockDate.set('2026-04-03T09:00:00.000Z');
  installClipboard();
  installMatchMedia();
  globalToastStore.dismissAllToasts();
  document.body.style.removeProperty('--bk-device-pixel-ratio');
